<?php
/** Transformers and fine-tuning: embeddings, attention, the transformer, pre-training and fine-tuning, LoRA and quantisation. */

return [
    'id' => 'dl-advanced', 'family' => 'dl', 'after' => 'dl-base',
    'title' => L('Transformer e fine-tuning', 'Transformers and Fine-tuning'), 'short' => L('DL avanzato', 'DL Advanced'), 'level' => L('Avanzato', 'Advanced'),
    'desc' => L('Dentro i modelli linguistici: embedding, attention, l’architettura transformer, pre-addestramento e fine-tuning, LoRA e quantizzazione.', 'Inside language models: embeddings, attention, the transformer architecture, pre-training and fine-tuning, LoRA and quantisation.'),
    'lessons' => [
        lesson('embeddings', L('Tokenizzazione ed embedding', 'Tokenisation and embeddings'), [
            P('Prima di tutto il testo viene diviso in **token** da un tokenizzatore e ogni token diventa un numero (il suo id nel vocabolario). Poi uno strato di **embedding** trasforma ogni id in un vettore di centinaia o migliaia di numeri, imparato durante l’addestramento.', 'First the text is split into **tokens** by a tokeniser and each token becomes a number (its id in the vocabulary). Then an **embedding** layer turns each id into a vector of hundreds or thousands of numbers, learned during training.'),
            C('from transformers import AutoTokenizer

tok = AutoTokenizer.from_pretrained("bert-base-multilingual-cased")
ids = tok("Il gatto dorme")["input_ids"]
print(ids)                               # es. [101, 10265, 31117, 10115, …, 102]
print(tok.convert_ids_to_tokens(ids))    # [\'[CLS]\', \'Il\', \'gatto\', …]

emb = torch.nn.Embedding(num_embeddings=50_000, embedding_dim=768)', 'python'),
            P('Negli embedding le parole con significato simile finiscono vicine. Da solo però un embedding non sa il **contesto**: “pesca” è lo stesso vettore nel frutto e nello sport. È l’attention a sistemare le cose.', 'In embeddings words with similar meaning end up close together. On its own, though, an embedding does not know **context**: “bank” is the same vector for a river and for money. Attention fixes that.'),
        ], [
            Q('e1', L('Che cosa fa il tokenizzatore?', 'What does the tokeniser do?'), [L('Divide il testo in token e li numera', 'Splits text into tokens and numbers them'), L('Traduce il testo', 'Translates the text'), L('Corregge gli errori', 'Fixes mistakes'), L('Comprime il file', 'Compresses the file')], 0, L('Ogni token ha un id.', 'Each token has an id.')),
            Q('e2', L('Che cosa produce uno strato di embedding?', 'What does an embedding layer produce?'), [L('Un vettore per ogni token', 'A vector per token'), L('Una sola parola', 'A single word'), L('Un’immagine', 'An image'), L('Una probabilità', 'A probability')], 0, L('Imparato durante il training.', 'Learned during training.')),
            Q('e3', L('Che cosa manca a un embedding da solo?', 'What does an embedding alone lack?'), [L('Il contesto della frase', 'The sentence context'), L('I numeri', 'Numbers'), L('Il vocabolario', 'The vocabulary'), L('La GPU', 'The GPU')], 0, L('Ci pensa l’attention.', 'Attention handles it.')),
        ], task('python', L('Crea `emb = torch.nn.Embedding(...)` con un vocabolario di `32000` token e vettori di dimensione `512`.', 'Create `emb = torch.nn.Embedding(...)` with a vocabulary of `32000` tokens and vectors of size `512`.'), "import torch", [re('emb\s*=\s*torch\.nn\.Embedding\s*\(\s*(num_embeddings\s*=\s*)?32_?000\s*,\s*(embedding_dim\s*=\s*)?512\s*\)', L('L’embedding giusto', 'The right embedding'))], '', 'emb = torch.nn.Embedding(32000, 512)'), [
            dOrder(pSort(), [L('Testo', 'Text'), L('Token', 'Tokens'), L('Id del vocabolario', 'Vocabulary ids'), L('Vettori di embedding', 'Embedding vectors'), L('Strati transformer', 'Transformer layers')], L('Dal testo ai vettori.', 'From text to vectors.')),
            dFlash(pFlash(), [[L('Ogni token ha un id nel vocabolario', 'Each token has a vocabulary id'), true], [L('Gli embedding sono scritti a mano', 'Embeddings are written by hand'), false], [L('Parole simili hanno embedding vicini', 'Similar words have nearby embeddings'), true], [L('Un embedding da solo capisce il contesto', 'An embedding alone understands context'), false]], L('Prima i numeri, poi il senso.', 'Numbers first, then meaning.')),
        ]),
        lesson('attention', L('L’attention', 'Attention'), [
            P('L’**attention** permette a ogni token di “guardare” gli altri e prendere informazioni da quelli rilevanti. Ogni token produce tre vettori: **query** (cosa cerco), **key** (cosa offro), **value** (il contenuto). Il peso tra due token è il prodotto scalare query·key, passato in una softmax.', '**Attention** lets each token “look at” the others and take information from the relevant ones. Each token produces three vectors: **query** (what I look for), **key** (what I offer), **value** (the content). The weight between two tokens is the query·key dot product, passed through a softmax.'),
            C('import torch, math

def attention(Q, K, V):
    punteggi = Q @ K.transpose(-2, -1) / math.sqrt(K.shape[-1])
    pesi = torch.softmax(punteggi, dim=-1)   # quanto ogni token guarda gli altri
    return pesi @ V', 'python'),
            P('Si divide per la radice della dimensione per tenere stabili i numeri. La **multi-head attention** fa più attention in parallelo, così ogni “testa” impara relazioni diverse (sintassi, riferimenti, argomento).', 'You divide by the square root of the dimension to keep numbers stable. **Multi-head attention** runs several attentions in parallel, so each “head” learns different relations (syntax, references, topic).'),
        ], [
            Q('a1', L('Che cosa rappresenta la query?', 'What does the query represent?'), [L('Che cosa cerca il token', 'What the token is looking for'), L('Il contenuto da passare', 'The content to pass on'), L('La posizione', 'The position'), L('Il vocabolario', 'The vocabulary')], 0, L('La key è cosa offre.', 'The key is what it offers.')),
            Q('a2', L('Perché si divide per √d?', 'Why divide by √d?'), [L('Per tenere stabili i valori prima della softmax', 'To keep values stable before softmax'), L('Per risparmiare memoria', 'To save memory'), L('Per arrotondare', 'To round'), L('Non si divide', 'You do not')], 0, L('Prodotti troppo grandi saturano la softmax.', 'Large products saturate the softmax.')),
            Q('a3', L('A che cosa servono più teste di attention?', 'What are multiple attention heads for?'), [L('Imparare relazioni diverse in parallelo', 'Learning different relations in parallel'), L('Elaborare più lingue', 'Handling more languages'), L('Usare meno GPU', 'Using fewer GPUs'), L('Leggere immagini', 'Reading images')], 0, L('Una guarda la sintassi, una i riferimenti…', 'One watches syntax, one references…')),
        ], task('python', L('Completa `attention`: calcola i `pesi` con `torch.softmax(punteggi, dim=-1)` e restituisci `pesi @ V`.', 'Complete `attention`: compute `pesi` with `torch.softmax(punteggi, dim=-1)` and return `pesi @ V`.'), "def attention(Q, K, V):\n    punteggi = Q @ K.transpose(-2, -1) / math.sqrt(K.shape[-1])\n    ", [re('pesi\s*=\s*torch\.softmax\s*\(\s*punteggi\s*,\s*dim\s*=\s*-1\s*\)', L('Softmax sui punteggi', 'Softmax over the scores')), re('return\s+pesi\s*@\s*V', L('Media pesata dei value', 'Weighted average of values'))], '', "pesi = torch.softmax(punteggi, dim=-1)\n    return pesi @ V"), [
            dMatch(pMatch(), [['Query', L('Cosa cerco', 'What I look for')], ['Key', L('Cosa offro', 'What I offer')], ['Value', L('Il contenuto', 'The content')], ['Softmax', L('Trasforma i punteggi in pesi', 'Turns scores into weights')], ['Multi-head', L('Più attention in parallelo', 'Several attentions in parallel')]], L('I pezzi dell’attention.', 'The pieces of attention.')),
            dOrder(pSort(), ['punteggi = Q @ K.transpose(-2, -1)', 'punteggi = punteggi / math.sqrt(d)', 'pesi = torch.softmax(punteggi, dim=-1)', 'uscita = pesi @ V'], L('Prodotto, scala, softmax, media pesata.', 'Product, scale, softmax, weighted average.')),
        ]),
        lesson('transformer', L('Il transformer', 'The transformer'), [
            P('Il **transformer** (2017) è una pila di blocchi uguali: ogni blocco ha attention, una piccola rete *feed-forward*, connessioni residue e normalizzazione. Poiché l’attention non conosce l’ordine, si aggiunge un’informazione di **posizione** agli embedding.', 'The **transformer** (2017) is a stack of identical blocks: each block has attention, a small feed-forward network, residual connections and normalisation. Since attention does not know order, **position** information is added to the embeddings.'),
            C('Ingresso → embedding + posizione
  └─ blocco × N:  attention (mascherata) → somma e normalizza
                  feed-forward          → somma e normalizza
→ strato finale → probabilità del prossimo token', 'text'),
            P('I modelli **decoder-only** (come GPT, Claude, Llama, Mistral) usano un’attention **mascherata**: ogni token vede solo quelli precedenti, perché devono prevedere il successivo. I modelli **encoder** (come BERT) vedono tutta la frase e sono ottimi per classificare e creare embedding.', '**Decoder-only** models (like GPT, Claude, Llama, Mistral) use **masked** attention: each token only sees the previous ones, because they must predict the next. **Encoder** models (like BERT) see the whole sentence and are great for classifying and making embeddings.'),
        ], [
            Q('f1', L('Perché si aggiunge la posizione agli embedding?', 'Why add position to the embeddings?'), [L('L’attention da sola non conosce l’ordine', 'Attention alone does not know order'), L('Per colorare i token', 'To colour tokens'), L('Per comprimere', 'To compress'), L('Non si aggiunge', 'It is not added')], 0, L('“Cane morde uomo” ≠ “uomo morde cane”.', '“Dog bites man” ≠ “man bites dog”.')),
            Q('f2', L('Che cosa vede un token in un decoder-only?', 'What does a token see in a decoder-only model?'), [L('Solo i token precedenti', 'Only the previous tokens'), L('Tutta la frase', 'The whole sentence'), L('Solo il successivo', 'Only the next one'), L('Nessun token', 'No tokens')], 0, L('Attention mascherata.', 'Masked attention.')),
            Q('f3', L('Per creare embedding di frasi è ottimo un modello…', 'For making sentence embeddings a good model is…'), [L('Encoder, come BERT', 'Encoder, like BERT'), L('Solo decoder', 'Decoder only'), L('Convoluzionale', 'Convolutional'), L('K-means', 'K-means')], 0, L('Vede tutto il contesto.', 'It sees the whole context.')),
        ], task('text', L('Abbina ogni modello al suo tipo, uno per riga come `modello: tipo`. Modelli: `BERT`, `Llama`. Tipi: encoder, decoder.', 'Match each model to its type, one per line as `model: type`. Models: `BERT`, `Llama`. Types: encoder, decoder.'), '', [re('BERT\s*:\s*encoder', L('BERT è un encoder', 'BERT is an encoder')), re('Llama\s*:\s*decoder', L('Llama è un decoder', 'Llama is a decoder'))], '', "BERT: encoder\nLlama: decoder"), [
            dMatch(pMatch(), [['Attention', L('Mescola informazioni tra token', 'Mixes information between tokens')], ['Feed-forward', L('Elabora ogni token', 'Processes each token')], [L('Connessione residua', 'Residual connection'), L('Somma l’ingresso all’uscita', 'Adds input to output')], [L('Maschera', 'Mask'), L('Nasconde il futuro', 'Hides the future')], [L('Posizione', 'Position'), L('L’ordine dei token', 'Token order')]], L('Dentro un blocco transformer.', 'Inside a transformer block.')),
            dFlash(pFlash(), [[L('Il transformer è stato presentato nel 2017', 'The transformer was introduced in 2017'), true], [L('Un decoder vede i token futuri', 'A decoder sees future tokens'), false], [L('Un transformer è una pila di blocchi uguali', 'A transformer is a stack of identical blocks'), true], [L('L’attention conosce l’ordine senza aiuto', 'Attention knows order without help'), false]], L('L’architettura dietro gli LLM.', 'The architecture behind LLMs.')),
        ]),
        lesson('finetune', L('Pre-addestramento e fine-tuning', 'Pre-training and fine-tuning'), [
            P('Un LLM nasce dal **pre-addestramento** su enormi quantità di testo: costa milioni e lo fanno pochi laboratori. Poi si **adatta**: con il **fine-tuning su istruzioni** impara a seguire richieste, con il feedback umano (**RLHF**) o metodi simili a essere utile e sicuro.', 'An LLM is born from **pre-training** on huge amounts of text: it costs millions and few labs do it. Then it is **adapted**: with **instruction fine-tuning** it learns to follow requests, with human feedback (**RLHF**) or similar methods to be helpful and safe.'),
            P('Anche tu puoi fare fine-tuning di un modello aperto sui tuoi esempi, per uno stile o un compito molto specifico. Ma prima prova prompt migliori e **RAG**: spesso bastano, costano meno e si aggiornano subito. Il fine-tuning insegna un **comportamento**, non è un buon modo per aggiungere **fatti**.', 'You too can fine-tune an open model on your examples, for a very specific style or task. But try better prompts and **RAG** first: they often suffice, cost less and update instantly. Fine-tuning teaches a **behaviour**; it is not a good way to add **facts**.'),
            C('{"messages": [{"role": "user", "content": "Riassumi il verbale…"},
              {"role": "assistant", "content": "• Decisione: … • Prossimi passi: …"}]}
{"messages": [{"role": "user", "content": "Riassumi il verbale…"},
              {"role": "assistant", "content": "• Decisione: … • Prossimi passi: …"}]}', 'json'),
        ], [
            Q('t1', L('Che cosa insegna bene il fine-tuning?', 'What does fine-tuning teach well?'), [L('Uno stile o un comportamento', 'A style or a behaviour'), L('I fatti di ieri', 'Yesterday’s facts'), L('Una nuova lingua di programmazione dal nulla', 'A new programming language from scratch'), L('Niente', 'Nothing')], 0, L('Per i fatti c’è RAG.', 'For facts there is RAG.')),
            Q('t2', L('Che cosa provare prima del fine-tuning?', 'What should you try before fine-tuning?'), [L('Prompt migliori e RAG', 'Better prompts and RAG'), L('Un modello più vecchio', 'An older model'), L('Più GPU', 'More GPUs'), L('Niente', 'Nothing')], 0, L('Più economici e flessibili.', 'Cheaper and more flexible.')),
            Q('t3', L('Che cos’è RLHF?', 'What is RLHF?'), [L('Addestramento con feedback umano', 'Training with human feedback'), L('Un formato di file', 'A file format'), L('Un tipo di GPU', 'A type of GPU'), L('Un linguaggio', 'A language')], 0, L('Reinforcement learning from human feedback.', 'Reinforcement learning from human feedback.')),
        ], task('json', L('Scrivi un esempio di addestramento in formato JSON con `messages`: un messaggio `user` che chiede di tradurre “ciao” e la risposta `assistant` “hello”.', 'Write a training example in JSON format with `messages`: a `user` message asking to translate “ciao” and the `assistant` answer “hello”.'), '', [re('"messages"\s*:\s*\[', L('C’è l’elenco dei messaggi', 'There is the message list')), re('"role"\s*:\s*"user"\s*,\s*"content"\s*:\s*"[^"]*ciao', L('La richiesta dell’utente', 'The user request')), re('"role"\s*:\s*"assistant"\s*,\s*"content"\s*:\s*"[^"]*hello', L('La risposta attesa', 'The expected answer'))], '', '{"messages": [{"role": "user", "content": "Traduci in inglese: ciao"}, {"role": "assistant", "content": "hello"}]}'), [
            dOrder(pSort(), [L('Pre-addestramento su testo enorme', 'Pre-training on huge text'), L('Fine-tuning su istruzioni', 'Instruction fine-tuning'), L('Feedback umano (RLHF)', 'Human feedback (RLHF)'), L('Uso tramite chat e API', 'Use through chat and API')], L('La vita di un LLM.', 'An LLM’s life.')),
            dFlash(pFlash(), [[L('Il fine-tuning è il modo migliore per aggiungere fatti nuovi', 'Fine-tuning is the best way to add new facts'), false], [L('Il pre-addestramento costa moltissimo', 'Pre-training costs a great deal'), true], [L('Si può fare fine-tuning di modelli aperti', 'Open models can be fine-tuned'), true], [L('Prima di fare fine-tuning conviene provare RAG', 'Try RAG before fine-tuning'), true]], L('Adattare con giudizio.', 'Adapt wisely.')),
        ]),
        lesson('lora', L('LoRA e quantizzazione', 'LoRA and quantisation'), [
            P('Fare fine-tuning di tutti i miliardi di parametri richiede molte GPU. **LoRA** (Low-Rank Adaptation) congela il modello e addestra solo piccole matrici aggiuntive: una frazione minima dei parametri, risultati spesso vicini al fine-tuning completo.', 'Fine-tuning all billions of parameters needs many GPUs. **LoRA** (Low-Rank Adaptation) freezes the model and trains only small extra matrices: a tiny fraction of the parameters, with results often close to full fine-tuning.'),
            C('from peft import LoraConfig, get_peft_model

config = LoraConfig(r=16, lora_alpha=32, target_modules=["q_proj", "v_proj"], lora_dropout=0.05)
modello = get_peft_model(modello_base, config)
modello.print_trainable_parameters()   # es. 0,1% dei parametri', 'python'),
            P('La **quantizzazione** salva i pesi con meno bit (8 o 4 invece di 16): il modello occupa molta meno memoria e gira su hardware più modesto, con una piccola perdita di qualità. **QLoRA** unisce le due idee: LoRA su un modello quantizzato a 4 bit.', '**Quantisation** stores weights with fewer bits (8 or 4 instead of 16): the model takes far less memory and runs on humbler hardware, with a small loss of quality. **QLoRA** combines both ideas: LoRA on a 4-bit quantised model.'),
        ], [
            Q('o1', L('Che cosa addestra LoRA?', 'What does LoRA train?'), [L('Piccole matrici aggiuntive', 'Small extra matrices'), L('Tutti i parametri', 'All parameters'), L('Solo il tokenizzatore', 'Only the tokeniser'), L('Niente', 'Nothing')], 0, L('Il modello base resta congelato.', 'The base model stays frozen.')),
            Q('o2', L('Che cosa fa la quantizzazione?', 'What does quantisation do?'), [L('Usa meno bit per i pesi', 'Uses fewer bits for weights'), L('Aggiunge parametri', 'Adds parameters'), L('Traduce il modello', 'Translates the model'), L('Cifra i dati', 'Encrypts data')], 0, L('Meno memoria, poca perdita.', 'Less memory, little loss.')),
            Q('o3', L('Che cos’è QLoRA?', 'What is QLoRA?'), [L('LoRA su un modello quantizzato', 'LoRA on a quantised model'), L('Una GPU', 'A GPU'), L('Un dataset', 'A dataset'), L('Un tokenizzatore', 'A tokeniser')], 0, L('Fine-tuning su una sola GPU.', 'Fine-tuning on a single GPU.')),
        ], task('python', L('Crea `config = LoraConfig(...)` con `r=8`, `lora_alpha=16` e `target_modules=["q_proj", "v_proj"]`.', 'Create `config = LoraConfig(...)` with `r=8`, `lora_alpha=16` and `target_modules=["q_proj", "v_proj"]`.'), "from peft import LoraConfig", [re('config\s*=\s*LoraConfig\s*\(', L('La configurazione', 'The configuration')), re('\br\s*=\s*8\b', L('Rango 8', 'Rank 8')), re('lora_alpha\s*=\s*16', L('Alpha 16', 'Alpha 16')), re('target_modules\s*=\s*\[\s*["\']q_proj["\']\s*,\s*["\']v_proj["\']\s*\]', L('I moduli giusti', 'The right modules'))], '', 'config = LoraConfig(r=8, lora_alpha=16, target_modules=["q_proj", "v_proj"])'), [
            dMatch(pMatch(), [['LoRA', L('Addestra poche matrici extra', 'Trains a few extra matrices')], [L('Quantizzazione', 'Quantisation'), L('Pesi con meno bit', 'Weights with fewer bits')], ['QLoRA', L('LoRA su modello a 4 bit', 'LoRA on a 4-bit model')], ['r', L('Rango delle matrici LoRA', 'Rank of LoRA matrices')]], L('Adattare con poche risorse.', 'Adapting with few resources.')),
            dFlash(pFlash(), [[L('LoRA addestra tutti i parametri', 'LoRA trains every parameter'), false], [L('Un modello a 4 bit occupa meno memoria di uno a 16', 'A 4-bit model takes less memory than a 16-bit one'), true], [L('La quantizzazione non cambia mai la qualità', 'Quantisation never changes quality'), false], [L('Con QLoRA si può adattare un modello su una sola GPU', 'With QLoRA you can adapt a model on a single GPU'), true]], L('Meno bit, meno parametri, stesso obiettivo.', 'Fewer bits, fewer parameters, same goal.')),
        ]),
    ],
];
